import {title,colors} from './engine.js';
export const W=540,H=960;
export class BattleView {
 constructor(stage,sprite){this.stage=stage;this.sprite=sprite;this.scenery=stage.querySelector('#scenery');this.canvas=stage.querySelector('#effects');for(const c of [this.scenery,this.canvas]){c.width=W;c.height=H}this.ctx=this.canvas.getContext('2d');this.bg=this.scenery.getContext('2d');this.fighters=[];this.clock=0;this.particles=[];this.effects=[];this.images={};this.cinematic=true;this.arena='stadium';this.label=null;this.notice=null;this.flash=0;this.shake=0;for(const name of ['fireball','waterwisp','electroball','energyball','shadowball','iceball','rock1','rock2','fist','foot','topbite','bottombite','leftslash','rightslash','impact','lightning','poisonwisp','sword'])this.load(name,'assets/fx/'+name+'.png');this.load('tiles','assets/general-tiles.png');this.load('building','assets/building-tiles.png');}
 load(name,src){const i=new Image();i.onload=()=>{this.images[name]=i;if(['tiles','building'].includes(name))this.drawArena()};i.src=src;return i}
 home(p){return {x:[116,270,424][p.slot],y:p.team===0?[325,258,325][p.slot]:[682,748,682][p.slot]}}
 mount(fighters){this.fighters=fighters;this.particles=[];this.effects=[];this.label=null;this.notice=null;this.clock=0;const host=this.stage.querySelector('#fighters');host.replaceChildren(...fighters.map(p=>{p.pos={...this.home(p)};p.motion=null;p.hitUntil=0;p.charge=false;p.face=p.team===0?1:-1;const el=document.createElement('div');el.className='overhead-fighter';el.id=p.uid;const img=document.createElement('img');img.alt=title(p.name);img.className='overhead-sprite';this.sprite(img,p.id,true);const shadow=document.createElement('i');el.append(shadow,img);p.el=el;return el}));this.drawHUD();this.updateSprites()}
 teamName(t){const ids=this.fighters.filter(p=>p.team===t).map(p=>p.id).sort((a,b)=>a-b).join(',');return ids==='382,383,384'?'HOENN TRIO':ids==='483,484,487'?'SINNOH TRIO':t===0?'TEAM EMERALD':'TEAM CRIMSON'}
 drawHUD(){for(let t=0;t<2;t++){const board=this.stage.querySelector(t?'#hud-bottom':'#hud-top');board.replaceChildren();const heading=document.createElement('strong');heading.className='hud-team-name';heading.textContent=this.teamName(t);board.append(heading);const row=document.createElement('div');row.className='hud-row';for(const p of this.fighters.filter(p=>p.team===t)){const box=document.createElement('div');box.className='hud-mon';box.id='hud-'+p.uid;const img=document.createElement('img');this.sprite(img,p.id,false);img.alt='';const content=document.createElement('div');const name=document.createElement('strong');name.textContent=title(p.name);const track=document.createElement('div');track.className='hud-hp-track';const fill=document.createElement('i');fill.style.width='100%';track.append(fill);const hp=document.createElement('span');hp.className='hud-hp-text';hp.textContent=p.hp+'/'+p.max;content.append(name,track,hp);box.append(img,content);row.append(box)}board.append(row)}}
 updateHP(p){const box=document.getElementById('hud-'+p.uid);box.querySelector('.hud-hp-track i').style.width=Math.max(0,p.hp/p.max*100)+'%';box.querySelector('.hud-hp-text').textContent=p.hp+'/'+p.max;box.classList.toggle('fainted',p.hp<=0);box.classList.toggle('low-hp',p.hp>0&&p.hp/p.max<.25);p.el.setAttribute('aria-label',`${title(p.name)}, ${p.hp} of ${p.max} HP`)}
 move(p,to,duration,arc=0){p.motion={from:{...p.pos},to,start:this.clock,duration:duration/1000,arc};}
 async motion(p,to,duration,wait,arc=0){this.move(p,to,duration,arc);await wait(duration)}
 announce(p,move){this.label={p,text:title(p.name)+'  '+title(move.name),color:colors[move.type]};}
 message(text,duration=700,large=false){this.notice={text,until:this.clock+duration/1000,large};}
 addFx(kind,from,to,color,duration=450,extra={}){this.effects.push({kind,from:{...from},to:{...to},color,start:this.clock,duration:duration/1000,...extra})}
 burst(pos,color,count=22){for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,v=60+Math.random()*140;this.particles.push({x:pos.x,y:pos.y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,size:2+Math.random()*4,life:.3+Math.random()*.4,max:.7,color})}}
 damage(p,text,critical=false){this.effects.push({kind:'text',from:{...p.pos},to:{...p.pos},text,critical,color:critical?'#ffe58a':'#ffffff',start:this.clock,duration:.8})}
 impact(p,color,heavy=false){p.hitUntil=this.clock+.22;this.burst(p.pos,color,heavy?35:18);this.addFx('impact',p.pos,p.pos,color,220);if(this.cinematic){this.flash=heavy?.22:.07;this.flashColor=color;this.shake=heavy?6:2.5}}
 updateSprites(){for(const p of this.fighters){if(p.motion){const m=p.motion,t=Math.min(1,(this.clock-m.start)/m.duration),e=t*t*(3-2*t);p.pos.x=m.from.x+(m.to.x-m.from.x)*e;p.pos.y=m.from.y+(m.to.y-m.from.y)*e-Math.sin(t*Math.PI)*m.arc;if(t>=1)p.motion=null}const img=p.el.querySelector('img'),hit=p.hitUntil>this.clock;p.el.style.left=p.pos.x/W*100+'%';p.el.style.top=p.pos.y/H*100+'%';p.el.style.zIndex=Math.round(p.pos.y);p.el.classList.toggle('fainted',p.hp<=0);p.el.classList.toggle('charging',!!p.charge);p.el.classList.toggle('struck',hit);p.el.style.setProperty('--aura',p.aura||'#ffffff');img.style.scale=(p.face===1?-1:1)+' 1';p.el.style.setProperty('--bob',Math.sin(this.clock*3+p.slot)*2+'px')}}
 drawArena(){const c=this.bg;c.clearRect(0,0,W,H);c.imageSmoothingEnabled=false;const forest=this.arena==='forest',lava=this.arena==='volcano';c.fillStyle=forest?'#527348':lava?'#544852':'#777987';c.fillRect(0,0,W,H);const R=(()=>{let s=81;return()=>{s=(s*16807)%2147483647;return s/2147483647}})();
 // Flat orthographic tiles: every row remains the same scale, with no horizon.
 for(let row=0;row<40;row++)for(let col=0;col<18;col++){let x=col*32-(row%2?16:0),y=row*26;c.fillStyle=forest?(R()>.5?'#56764b':'#527146'):lava?(R()>.5?'#62535a':'#594c54'):(R()>.5?'#858592':'#7c7d8c');c.fillRect(x+1,y+1,30,24);c.fillStyle=forest?'#96a77122':lava?'#ca947122':'#c4c1cd33';c.fillRect(x+2,y+2,28,1);c.fillStyle=forest?'#2e593333':'#302e4533';c.fillRect(x+2,y+24,28,1);if(forest){c.fillStyle='#8da16a55';c.fillRect(x+10+R()*10,y+8+R()*9,2,4)}}
 // Original game tiles provide stone texture and familiar overworld details.
 if(this.images.tiles){c.globalAlpha=forest?.12:.18;for(let y=130;y<850;y+=32)for(let x=24;x<520;x+=32)c.drawImage(this.images.tiles,48,128,16,16,x,y,32,32);c.globalAlpha=1}
 c.fillStyle=lava?'#302b35':'#333b4a';c.fillRect(0,0,20,H);c.fillRect(W-20,0,20,H);c.fillRect(0,0,W,26);c.fillRect(0,H-26,W,26);c.fillStyle=lava?'#9d684d':'#a7abb2';for(let y=24;y<H;y+=44){c.fillRect(3,y,12,31);c.fillRect(W-15,y,12,31)}
 for(const [x,y] of [[26,145],[468,145],[26,803],[468,803]]){c.fillStyle='#323b48';c.fillRect(x+5,y+5,42,42);c.fillStyle='#b3b5be';c.fillRect(x,y,38,38);c.fillStyle='#8c909b';c.fillRect(x+3,y+3,32,32);c.fillStyle='#c2c4cc';c.fillRect(x+5,y+4,27,4);if(this.images.building)c.drawImage(this.images.building,8,0,16,16,x+3,y+3,32,32)}
 if(forest&&this.images.tiles){for(const x of [-12,492])for(let y=180;y<800;y+=90){c.save();c.drawImage(this.images.tiles,0,16,48,64,x,y,64,85);c.globalCompositeOperation='source-atop';c.fillStyle='#2b69342b';c.fillRect(x,y,64,85);c.restore()}}
 if(lava){c.save();c.strokeStyle='#ffb255';c.lineWidth=4;c.shadowColor='#ff742d';c.shadowBlur=10;for(const side of [30,510]){c.beginPath();c.moveTo(side,130);for(let y=150;y<840;y+=30)c.lineTo(side+(R()-.5)*38,y);c.stroke()}c.restore()}
 const shade=c.createRadialGradient(270,480,160,270,480,650);shade.addColorStop(0,'#15152200');shade.addColorStop(1,'#11122188');c.fillStyle=shade;c.fillRect(0,0,W,H)}
 asset(c,name,x,y,w,h,rotation=0,alpha=1){const img=this.images[name];if(!img)return false;c.save();c.translate(x,y);c.rotate(rotation);c.globalAlpha*=alpha;c.drawImage(img,-w/2,-h/2,w,h);c.restore();return true}
 draw(dt){this.clock+=dt;this.updateSprites();const c=this.ctx;c.clearRect(0,0,W,H);c.imageSmoothingEnabled=false;c.save();if(this.shake>.1){const n=this.shake;c.translate((Math.random()-.5)*n,(Math.random()-.5)*n);this.shake*=Math.exp(-dt*13)}
 for(const p of this.particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=100*dt;c.globalAlpha=Math.max(0,p.life/p.max);c.fillStyle=p.color;c.fillRect(p.x,p.y,p.size,p.size)}this.particles=this.particles.filter(p=>p.life>0);c.globalAlpha=1;
 for(const e of this.effects){const t=(this.clock-e.start)/e.duration;if(t>1)continue;const x=e.from.x+(e.to.x-e.from.x)*Math.min(1,t*1.6),y=e.from.y+(e.to.y-e.from.y)*Math.min(1,t*1.6),a=Math.atan2(e.to.y-e.from.y,e.to.x-e.from.x),alpha=Math.min(1,(1-t)*4);c.save();c.globalAlpha=alpha;c.fillStyle=e.color;c.strokeStyle=e.color;
 if(e.kind==='beam'||e.kind==='bolt'){c.save();c.shadowColor=e.color;c.shadowBlur=this.cinematic?15:0;c.lineCap='round';c.lineWidth=e.kind==='bolt'?5:16;c.beginPath();c.moveTo(e.from.x,e.from.y);for(let i=1;i<=14;i++){const q=i/14,j=e.kind==='bolt'?(Math.random()-.5)*20:Math.sin(q*18-this.clock*30)*3;c.lineTo(e.from.x+(x-e.from.x)*q+Math.cos(a+Math.PI/2)*j,e.from.y+(y-e.from.y)*q+Math.sin(a+Math.PI/2)*j)}c.stroke();c.lineWidth=4;c.strokeStyle='#fff';c.stroke();c.restore();this.asset(c,e.asset||'fireball',x,y,30,30,a)}
 else if(e.kind==='ground'){for(let i=0;i<7;i++){const q=Math.max(0,Math.min(1,t*2-i*.12)),px=e.from.x+(e.to.x-e.from.x)*i/6,py=e.from.y+(e.to.y-e.from.y)*i/6;c.fillStyle=e.color;c.beginPath();c.moveTo(px-12*q,py+10);c.lineTo(px,py-48*Math.sin(q*Math.PI*.7));c.lineTo(px+12*q,py+10);c.fill();this.asset(c,'rock1',px,py-18*q,30*q,38*q)}}
 else if(e.kind==='meteor'){for(let i=0;i<6;i++){const q=Math.min(1,Math.max(0,t*1.8-i*.1)),px=e.to.x+(i-3)*20,py=e.to.y-330+q*330;c.strokeStyle=e.color;c.lineWidth=5;c.beginPath();c.moveTo(px-35,py-60);c.lineTo(px,py);c.stroke();this.asset(c,'rock2',px,py,28,28,q*5)}}
 else if(e.kind==='slash'){this.asset(c,t<.5?'leftslash':'rightslash',e.to.x,e.to.y,110,110,a);c.lineWidth=4;for(let i=0;i<3;i++){c.beginPath();c.moveTo(e.to.x-35+i*10,e.to.y+35);c.lineTo(e.to.x+25+i*10,e.to.y-35);c.stroke()}}
 else if(e.kind==='bite'){this.asset(c,'topbite',e.to.x,e.to.y-25*(1-t),72,48);this.asset(c,'bottombite',e.to.x,e.to.y+25*(1-t),72,48)}
 else if(e.kind==='punch'||e.kind==='kick'){this.asset(c,e.kind==='punch'?'fist':'foot',e.to.x,e.to.y,62,62,Math.sin(t*8)*.3)}
 else if(e.kind==='tail'){c.lineWidth=12;c.beginPath();c.arc(e.to.x,e.to.y,35,-Math.PI/2+t*4,Math.PI/2+t*4);c.stroke()}
 else if(e.kind==='wave'){for(let i=0;i<3;i++){c.globalAlpha=alpha*(1-i*.2);c.lineWidth=3;c.beginPath();c.arc(x,y,18+i*13,0,Math.PI*2);c.stroke()}this.asset(c,e.asset||'waterwisp',x,y,50,50,a)}
 else if(e.kind==='impact'){this.asset(c,'impact',e.to.x,e.to.y,60+50*t,60+50*t);c.strokeStyle='#ffedc7';c.lineWidth=2;c.beginPath();c.arc(e.to.x,e.to.y,15+t*50,0,Math.PI*2);c.stroke()}
 else if(e.kind==='text'){c.textAlign='center';c.font=`bold ${e.critical?19:16}px monospace`;c.strokeStyle='#23202f';c.lineWidth=4;c.strokeText(e.text,e.to.x,e.to.y-42-t*35);c.fillText(e.text,e.to.x,e.to.y-42-t*35)}
 else {if(e.kind==='shuriken'){c.translate(x,y);c.rotate(t*15);for(let i=0;i<4;i++){c.rotate(Math.PI/2);c.beginPath();c.moveTo(0,0);c.lineTo(24,7);c.lineTo(8,10);c.fill()}}else{this.asset(c,e.asset||'shadowball',x,y,48,48,t*3);if(!this.images[e.asset||'shadowball']){c.beginPath();c.arc(x,y,16,0,7);c.fill()}}}c.restore()}
 this.effects=this.effects.filter(e=>this.clock-e.start<=e.duration);c.restore();if(this.flash>0){c.globalAlpha=this.flash;c.fillStyle=this.flashColor||'#fff';c.fillRect(0,0,W,H);c.globalAlpha=1;this.flash*=Math.exp(-dt*20)}
 if(this.label){const l=this.label,p=l.p.pos,y=Math.max(160,Math.min(810,p.y-67)),x=Math.max(120,Math.min(420,p.x));c.font='bold 11px monospace';const width=Math.min(310,c.measureText(l.text).width+22);c.fillStyle='#161722ee';c.strokeStyle='#d6d1d0';c.lineWidth=1;c.beginPath();c.roundRect(x-width/2,y-13,width,25,5);c.fill();c.stroke();c.fillStyle=l.color;c.textAlign='center';c.fillText(l.text,x,y+3,width-12)}
 if(this.notice&&this.clock<this.notice.until){const n=this.notice;c.textAlign='center';if(n.large){c.font='bold 56px monospace';c.lineWidth=7;c.strokeStyle='#252734';c.strokeText(n.text,270,490);c.fillStyle='#e8e4e5';c.fillText(n.text,270,490)}else{c.fillStyle='#171923ed';c.strokeStyle='#cac8d6';c.lineWidth=1;c.fillRect(85,465,370,36);c.strokeRect(85,465,370,36);c.fillStyle='#f1e8db';c.font='bold 15px monospace';c.fillText(n.text,270,489,350)}}}
}
